(()=>{'use strict';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let focus=null;const vd=$('#analysis-video'),player=vd.querySelector('video'),id=$('#analysis-image');let seek=0;
function close(d){d.close();if(d===vd){player.pause();player.removeAttribute('src');player.load();}document.body.style.overflow='';focus?.focus({preventScroll:true});}
function open(d){focus=document.activeElement;d.showModal();document.body.style.overflow='hidden';}
document.addEventListener('click',e=>{const v=e.target.closest('[data-video]'),im=e.target.closest('[data-image]'),c=e.target.closest('[data-close]');if(v){seek=Number(v.dataset.time)||0;vd.querySelector('h2').textContent=v.dataset.title+' · '+seek+'초부터';vd.querySelector('.player-message').textContent='영상 불러오는 중…';player.src=v.dataset.video;open(vd);player.load();player.play().catch(()=>{vd.querySelector('.player-message').textContent='재생 버튼을 눌러 시작하세요.';});}else if(im){id.querySelector('img').src=im.dataset.image;id.querySelector('img').alt=im.querySelector('img').alt;open(id);}else if(c)close(c.closest('dialog'));});
player.addEventListener('loadedmetadata',()=>{player.currentTime=Math.min(seek,Math.max(0,player.duration-.1));});player.addEventListener('playing',()=>vd.querySelector('.player-message').textContent='');player.addEventListener('error',()=>vd.querySelector('.player-message').textContent='영상을 불러오지 못했습니다. 잠시 뒤 다시 열어주세요.');[vd,id].forEach(d=>{d.addEventListener('cancel',e=>{e.preventDefault();close(d);});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close(d);}});});
const cards=$$('.material-card');function filter(){const q=$('#material-search').value.trim().toLowerCase(),g=$('#material-filter').value;let n=0;cards.forEach(c=>{const show=(!q||c.textContent.toLowerCase().includes(q))&&(g==='all'||c.dataset.group===g);c.hidden=!show;if(show)n++;});$('#material-count').textContent=n+' / '+cards.length+'편';$('#material-empty').hidden=n>0;}$('#material-search').addEventListener('input',filter);$('#material-filter').addEventListener('change',filter);filter();$('#material-expand').addEventListener('click',()=>cards.filter(c=>!c.hidden).forEach(c=>c.open=true));$('#material-collapse').addEventListener('click',()=>cards.forEach(c=>c.open=false));})();
